import{_ as t,o as l,c as e,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"凯·格雷厄姆（Katharine Graham）","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/凯·格雷厄姆.md","filePath":"04_people/凯·格雷厄姆.md"}'),i={name:"04_people/凯·格雷厄姆.md"};function h(o,a,d,n,s,u){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="凯·格雷厄姆-katharine-graham" tabindex="-1">凯·格雷厄姆（Katharine Graham） <a class="header-anchor" href="#凯·格雷厄姆-katharine-graham" aria-label="Permalink to &quot;凯·格雷厄姆（Katharine Graham）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>全名</td><td>Katharine Meyer Graham</td></tr><tr><td>出生</td><td>1917年6月16日，纽约</td></tr><tr><td>逝世</td><td>2001年7月17日（84岁）</td></tr><tr><td>职业</td><td>出版人、企业家</td></tr><tr><td>公司</td><td><a href="/03_companies/华盛顿邮报.html">华盛顿邮报</a></td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="早年" tabindex="-1">早年 <a class="header-anchor" href="#早年" aria-label="Permalink to &quot;早年&quot;">​</a></h3><ul><li>1917年生于纽约，父亲尤金·梅耶（Eugene Meyer）是富有的银行家</li><li>毕业于瓦萨学院和芝加哥大学</li><li>1933年父亲买下《华盛顿邮报》</li><li>1940年嫁入格雷厄姆家族，丈夫菲利普·格雷厄姆（Philip Graham）接管邮报</li></ul><h3 id="从主妇到掌门人" tabindex="-1">从主妇到掌门人 <a class="header-anchor" href="#从主妇到掌门人" aria-label="Permalink to &quot;从主妇到掌门人&quot;">​</a></h3><ul><li>长期在丈夫光环下，自信被严重压抑</li><li>1963年丈夫因抑郁症自杀，凯被迫接手</li><li>1969年将华盛顿邮报公司上市</li><li><strong>1971年成为华盛顿邮报公司CEO——美国首位《财富》500强女CEO</strong></li><li>1972年推动《华盛顿邮报》上市，并掌管旗下四家电视台和《新闻周刊》</li></ul><h2 id="水门事件" tabindex="-1">水门事件 <a class="header-anchor" href="#水门事件" aria-label="Permalink to &quot;水门事件&quot;">​</a></h2><h3 id="历史性时刻" tabindex="-1">历史性时刻 <a class="header-anchor" href="#历史性时刻" aria-label="Permalink to &quot;历史性时刻&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事件</th></tr></thead><tbody><tr><td>1972年6月</td><td>五人闯入水门大厦民主党总部</td></tr><tr><td>1972年</td><td>邮报记者鲍勃·伍德沃德和卡尔·伯恩斯坦持续追踪</td></tr><tr><td>1972-1974年</td><td>凯顶住白宫巨大压力，坚持发表调查报道</td></tr><tr><td>1974年8月</td><td>尼克松总统辞职</td></tr></tbody></table><h3 id="关键决策" tabindex="-1">关键决策 <a class="header-anchor" href="#关键决策" aria-label="Permalink to &quot;关键决策&quot;">​</a></h3><ul><li>白宫威胁取消邮报电视台执照、限制其上市</li><li>凯承受巨大心理压力（自称&quot;每天早上都在想是否该退缩&quot;）</li><li>依然坚持新闻独立原则，让记者放手报道</li><li><strong>水门事件使《华盛顿邮报》成为美国新闻自由的象征</strong></li></ul><h3 id="名言" tabindex="-1">名言 <a class="header-anchor" href="#名言" aria-label="Permalink to &quot;名言&quot;">​</a></h3><blockquote><p>&quot;决定发表那些报道是我做过最孤独的决定。&quot; —— 凯·格雷厄姆</p></blockquote><h2 id="与巴菲特的友谊" tabindex="-1">与巴菲特的友谊 <a class="header-anchor" href="#与巴菲特的友谊" aria-label="Permalink to &quot;与巴菲特的友谊&quot;">​</a></h2><h3 id="结识与投资" tabindex="-1">结识与投资 <a class="header-anchor" href="#结识与投资" aria-label="Permalink to &quot;结识与投资&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事件</th></tr></thead><tbody><tr><td>1973年</td><td>巴菲特以约1,060万美元买入华盛顿邮报公司约10%股份</td></tr><tr><td>1974年</td><td>巴菲特加入华盛顿邮报公司董事会</td></tr><tr><td>1974-2001年</td><td>巴菲特担任董事长达27年</td></tr><tr><td>1970s-2001年</td><td>凯与巴菲特建立深厚友谊，频繁请教商业决策</td></tr></tbody></table><h3 id="亦师亦友" tabindex="-1">亦师亦友 <a class="header-anchor" href="#亦师亦友" aria-label="Permalink to &quot;亦师亦友&quot;">​</a></h3><ul><li>凯缺乏商业背景，巴菲特成为她最重要的商业导师</li><li>巴菲特教会她理解市值、市盈率等基本商业概念</li><li>凯经常深夜打电话向巴菲特请教</li><li>巴菲特帮她抵御了收购威胁，保护了邮报的独立性</li><li>两人关系超越了商业伙伴，成为终身挚友</li></ul><h3 id="巴菲特的角色" tabindex="-1">巴菲特的角色 <a class="header-anchor" href="#巴菲特的角色" aria-label="Permalink to &quot;巴菲特的角色&quot;">​</a></h3><ul><li><strong>商业顾问</strong>：指导凯理解财务报表和公司治理</li><li><strong>董事会成员</strong>：27年任期中提供战略建议</li><li><strong>保护者</strong>：在敌意收购威胁时帮助凯设计防御方案</li><li><strong>精神支持</strong>：在凯最缺乏自信时给予鼓励</li></ul><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><h3 id="经典语录" tabindex="-1">经典语录 <a class="header-anchor" href="#经典语录" aria-label="Permalink to &quot;经典语录&quot;">​</a></h3><blockquote><p>&quot;凯是我见过的最杰出的CEO之一。在商业判断力方面，她比我所认识的大多数男性高管都更出色。&quot; —— 巴菲特</p></blockquote><blockquote><p>&quot;她接手邮报时对自己毫无信心，但她有一种品质——她会倾听，会学习，然后做出正确决策。&quot;</p></blockquote><blockquote><p>&quot;凯·格雷厄姆是我最敬佩的人之一。她从一个觉得自己什么都不知道的人，成长为美国最受尊敬的企业领袖。&quot;</p></blockquote><h3 id="在股东信中的提及" tabindex="-1">在股东信中的提及 <a class="header-anchor" href="#在股东信中的提及" aria-label="Permalink to &quot;在股东信中的提及&quot;">​</a></h3><ul><li>多次称赞华盛顿邮报作为优秀企业的典范</li><li>将凯列为最欣赏的CEO之一</li><li>以邮报为例说明&quot;经济护城河&quot;的概念——报纸在特定城市拥有垄断地位</li></ul><h2 id="个人回忆录" tabindex="-1">个人回忆录 <a class="header-anchor" href="#个人回忆录" aria-label="Permalink to &quot;个人回忆录&quot;">​</a></h2><ul><li>1997年出版自传《<strong>个人历史</strong>》（Personal History）</li><li>荣获<strong>1998年普利策传记奖</strong></li><li>坦诚记录了自己从缺乏自信到成为强势领导者的转变过程</li><li>成为无数女性的精神灯塔</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><h3 id="对新闻业" tabindex="-1">对新闻业 <a class="header-anchor" href="#对新闻业" aria-label="Permalink to &quot;对新闻业&quot;">​</a></h3><ul><li>水门事件重塑了美国新闻业的标准</li><li>证明了独立调查报道可以改变国家历史</li><li>《华盛顿邮报》在她的领导下成为世界顶级报纸之一</li></ul><h3 id="对女性" tabindex="-1">对女性 <a class="header-anchor" href="#对女性" aria-label="Permalink to &quot;对女性&quot;">​</a></h3><ul><li>作为首位《财富》500强女CEO，打破了企业界的性别天花板</li><li>证明了女性完全有能力领导大型企业</li><li>其自传激励了无数职业女性</li></ul><h3 id="对巴菲特投资理念" tabindex="-1">对巴菲特投资理念 <a class="header-anchor" href="#对巴菲特投资理念" aria-label="Permalink to &quot;对巴菲特投资理念&quot;">​</a></h3><ul><li>华盛顿邮报是巴菲特经典投资案例之一</li><li>1973年投资约1,060万美元，到2014年伯克希尔出售时价值超过<strong>12亿美元</strong></li><li>完美诠释了&quot;以合理价格买入伟大企业，长期持有&quot;的理念</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/华盛顿邮报.html">华盛顿邮报</a> - 领导的企业</li><li><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> - 挚友与董事</li><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 通过伯克希尔持有邮报股份</li></ul><hr><p><em>最后更新：2026-04-12</em></p><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/1973年/翻译.html">1973年</a></li><li><a href="./../01_letters/1974年/翻译.html">1974年</a></li><li><a href="./../01_letters/1977年/翻译.html">1977年</a></li><li><a href="./../01_letters/1978年/翻译.html">1978年</a></li><li><a href="./../01_letters/1979年/翻译.html">1979年</a></li><li><a href="./../01_letters/1983年/翻译.html">1983年</a></li><li><a href="./../01_letters/1984年/翻译.html">1984年</a></li><li><a href="./../01_letters/1985年/翻译.html">1985年</a></li><li><a href="./../01_letters/1991年/翻译.html">1991年</a></li><li><a href="./../01_letters/2003年/翻译.html">2003年</a></li><li><a href="./../01_letters/2014年/翻译.html">2014年</a></li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=华盛顿邮报相关">1988年：完整翻译|/01_letters/1988年/翻译</a></li></ul>',47)])])}const q=t(i,[["render",h]]);export{b as __pageData,q as default};
